def count_debts(grades):
    count = 0
    for grade in grades:
        if grade == 2:
            count += 1
    return count

print(count_debts([5, 2, 4, 2]))

def average(grades):
    if not grades:
        return None
    return sum(grades) / len(grades)

print(average([5, 4, 5]))
print(average([]))

def passing(grades, minimum=3):
    result = []
    for grade in grades:
        if grade >= minimum:
            result.append(grade)
    return result

print(passing([2, 3, 4, 5]))
print(passing([2, 3, 4, 5], minimum=4))

def average(grades):
    return sum(grades) / len(grades) if grades else None

def summary(grades):
    return {"count": len(grades),
            "average": average(grades),
            "debt": 2 in grades}

print(summary([2, 4, 5]))

def count_debts(grades):
    return grades.count(2)

assert count_debts([]) == 0
assert count_debts([3, 4, 5]) == 0
assert count_debts([2, 5, 2]) == 2
print("3 проверки выполнены")
